// Mills lead magnet: validate, normalize and enrich one form submission.
// To add the 16 industry guides later, add their slugs to GUIDES below (same shape).
const SITE = 'https://themillsglobal.com/';
const GUIDES = {
  "entry": {
    "service": "Mills Entry",
    "title": "Philippine Market Entry Readiness Checklist",
    "pdf": "assets/lead-magnets/entry-readiness-checklist.pdf"
  },
  "permits": {
    "service": "Mills Permits",
    "title": "Import Permit and Product Registration Checklist",
    "pdf": "assets/lead-magnets/permits-readiness-checklist.pdf"
  },
  "customs": {
    "service": "Mills Customs",
    "title": "Customs Clearance Readiness Checklist",
    "pdf": "assets/lead-magnets/customs-readiness-checklist.pdf"
  },
  "projects": {
    "service": "Mills Projects",
    "title": "Project Cargo Readiness Checklist",
    "pdf": "assets/lead-magnets/projects-readiness-checklist.pdf"
  },
  "marine": {
    "service": "Mills Marine",
    "title": "Vessel and Marine Equipment Readiness Checklist",
    "pdf": "assets/lead-magnets/marine-readiness-checklist.pdf"
  },
  "dangerous-goods": {
    "service": "Mills Dangerous Goods",
    "title": "Dangerous Goods Shipping Readiness Checklist",
    "pdf": "assets/lead-magnets/dangerous-goods-readiness-checklist.pdf"
  },
  "logistics": {
    "service": "Mills Logistics",
    "title": "Post-Clearance Delivery Readiness Checklist",
    "pdf": "assets/lead-magnets/logistics-readiness-checklist.pdf"
  },
  "packaging": {
    "service": "Mills Packaging",
    "title": "Export and Industrial Packaging Readiness Checklist",
    "pdf": "assets/lead-magnets/packaging-readiness-checklist.pdf"
  },
  "insurance": {
    "service": "Mills Insurance",
    "title": "Marine Cargo Insurance Readiness Checklist",
    "pdf": "assets/lead-magnets/insurance-readiness-checklist.pdf"
  },
  "time-critical": {
    "service": "Mills Time Critical",
    "title": "Priority Clearance Readiness Checklist",
    "pdf": "assets/lead-magnets/time-critical-readiness-checklist.pdf"
  },
  "advisory": {
    "service": "Mills Advisory",
    "title": "Philippine Trade Regulation Readiness Checklist",
    "pdf": "assets/lead-magnets/advisory-readiness-checklist.pdf"
  }
};

// Who is notified for each service. Replace the addresses with the person who owns that service.
const DEFAULT_OWNER = 'inquiry@themillsglobal.com';
const OWNERS = {
  'Mills Entry': DEFAULT_OWNER, 'Mills Permits': DEFAULT_OWNER, 'Mills Customs': DEFAULT_OWNER, 'Mills Projects': DEFAULT_OWNER,
  'Mills Marine': DEFAULT_OWNER, 'Mills Dangerous Goods': DEFAULT_OWNER, 'Mills Logistics': DEFAULT_OWNER, 'Mills Packaging': DEFAULT_OWNER,
  'Mills Insurance': DEFAULT_OWNER, 'Mills Time Critical': DEFAULT_OWNER, 'Mills Advisory': DEFAULT_OWNER
};

const b = $input.first().json.body || {};
const clean = (v) => String(v == null ? '' : v).trim();
const guide = clean(b.guide);
const email = clean(b.email).toLowerCase();
const digits = clean(b.phone).replace(/\D/g, '');
const g = GUIDES[guide];

let error = '';
if (clean(b.hp)) error = 'spam';
else if (!g) error = 'unknown guide: ' + guide;
else if (clean(b.name).length < 2) error = 'name';
else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) error = 'email';
else if (digits.length < 7 || digits.length > 15) error = 'phone';
else if (clean(b.company).length < 2) error = 'company';

const name = clean(b.name);
const FREE = ['gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 'icloud.com', 'live.com', 'proton.me', 'protonmail.com'];
const domain = email.split('@')[1] || '';
const fromAd = !!(clean(b.gclid) || clean(b.gbraid) || clean(b.wbraid));
// Hot = came from a Google ad, or used a company email address
const priority = (fromAd || (domain && !FREE.includes(domain))) ? 'Hot' : 'Normal';
return [{ json: {
  notify_to: (g && OWNERS[g.service]) || DEFAULT_OWNER,
  priority,
  valid: !error,
  error,
  submitted_at: clean(b.submitted_at) || new Date().toISOString(),
  guide,
  service: g ? g.service : '',
  guide_title: g ? g.title : clean(b.guide_title),
  pdf_url: g ? SITE + g.pdf : '',
  name,
  first_name: name.split(/\s+/).length > 1 ? name.split(/\s+/)[0] : '',
  last_name: name.split(/\s+/).length > 1 ? name.split(/\s+/).slice(1).join(' ') : name,
  first_name_greeting: name.split(/\s+/)[0],
  email,
  phone: clean(b.phone),
  company: clean(b.company),
  page: clean(b.page),
  gclid: clean(b.gclid), gbraid: clean(b.gbraid), wbraid: clean(b.wbraid),
  utm_source: clean(b.utm_source), utm_medium: clean(b.utm_medium), utm_campaign: clean(b.utm_campaign),
  utm_term: clean(b.utm_term), utm_content: clean(b.utm_content),
  lead_source: 'lead_magnet'
} }];

